let agents=[],selected=null;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,options={}){const r=await fetch(path,{headers:{'Content-Type':'application/json'},...options});const d=await r.json();if(!r.ok)throw Error(d.detail||d.error||'Something went wrong');return d}
function renderAgents(){$('#agent-count').textContent=agents.length;$('#agents').innerHTML=agents.length?agents.map(a=>`<button class="agent ${a.id===selected?.id?'selected':''}" data-id="${a.id}"><strong>${esc(a.name)}</strong><small>${esc(a.objective)}</small><span class="tag ${a.status}">${esc(a.version)} · ${esc(a.status)}</span><span class="test-count">${a.test_count} tests</span></button>`).join(''):'<p class="small-copy">No agents yet.</p>';document.querySelectorAll('.agent').forEach(b=>b.onclick=()=>selectAgent(+b.dataset.id))}
function showRuns(runs){$('#run-count').textContent=runs.length;$('#runs').innerHTML=runs.length?runs.map(r=>`<div class="run-item"><div><strong>${esc(r.name)}</strong><br><span class="tag">v${esc(r.version)} · ${esc(r.status)}</span></div><p>${esc(r.task)}</p><time>${esc(r.duration_ms)}ms<br>${esc(r.created_at.slice(0,16))}</time></div>`).join(''):'<p class="output empty">Your local execution trace will appear here.</p>'}
async function selectAgent(id){selected=await api(`/api/agents/${id}`);selected.version_id=selected.versions[0].id;selected.detail=await api(`/api/versions/${selected.version_id}`);$('#selected-title').textContent=selected.name;$('#selected-status').textContent=`${selected.detail.version} · ${selected.detail.status}`;$('#empty-state').hidden=true;$('#workbench').hidden=false;renderAgents();renderDetail()}
function renderDetail(){const d=selected.detail;$('#spec').textContent=JSON.stringify(d.specification,null,2);$('#tests').innerHTML=d.tests.length?d.tests.map(t=>`<div class="test"><strong>${esc(t.name)}</strong><small>${esc(t.prompt)}</small>${t.must_include?`<span class="tag">must include: ${esc(t.must_include)}</span>`:''}</div>`).join(''):'<p class="small-copy">No tests yet. Add one before evaluation.</p>';$('#promote').disabled=d.status==='approved';$('#promote').textContent=d.status==='approved'?'✓ Approved version':'Promote this version for use'}
async function refresh(){agents=await api('/api/agents');renderAgents();showRuns(await api('/api/runs'));if(selected&&agents.some(a=>a.id===selected.id))await selectAgent(selected.id)}
function setTab(tab){document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));document.querySelectorAll('.tab-panel').forEach(x=>x.hidden=x.id!==`${tab}-panel`)}
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));$('#new-agent').onclick=()=>$('#dialog').showModal();
$('#agent-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),data=Object.fromEntries(f);data.tools=f.getAll('tools');data.approval_actions=f.getAll('approval_actions');try{const v=await api('/api/agents',{method:'POST',body:JSON.stringify(data)});$('#dialog').close();e.target.reset();await refresh();await selectAgent(v.agent_id)}catch(err){alert(err.message)}});
$('#run').onclick=async()=>{const task=$('#task').value.trim();if(!task)return alert('Describe the work first.');const b=$('#run');b.disabled=true;b.textContent='Running…';$('#output').className='output';$('#output').textContent='Executing locally…';try{const r=await api(`/api/versions/${selected.version_id}/run`,{method:'POST',body:JSON.stringify({task})});$('#output').textContent=r.output;showRuns(await api('/api/runs'))}catch(err){$('#output').textContent=err.message}finally{b.disabled=false;b.innerHTML='Run version <b>→</b>'}};
$('#test-form').addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{await api(`/api/versions/${selected.version_id}/tests`,{method:'POST',body:JSON.stringify(data)});e.target.reset();selected.detail=await api(`/api/versions/${selected.version_id}`);renderDetail()}catch(err){alert(err.message)}});
$('#evaluate').onclick=async()=>{const b=$('#evaluate');b.disabled=true;b.textContent='Evaluating…';try{const r=await api(`/api/versions/${selected.version_id}/evaluate`,{method:'POST',body:'{}'});$('#evaluation').className='output';$('#evaluation').textContent=(r.passed?'PASS':'NEEDS REVIEW')+' · '+r.version+'\n\n'+r.results.map(x=>`${x.passed?'✓':'×'} ${x.test}: ${x.rationale}`).join('\n');showRuns(await api('/api/runs'))}catch(err){$('#evaluation').textContent=err.message}finally{b.disabled=false;b.textContent='Run evaluation suite'}};
$('#promote').onclick=async()=>{try{await api(`/api/versions/${selected.version_id}/promote`,{method:'POST',body:JSON.stringify({note:'Promoted locally from factory dashboard.'})});await refresh();alert('Version promoted. Future runs select this approved definition.')}catch(err){alert(err.message)}};
refresh().catch(e=>alert(e.message));
